import StarsRating from "./StarsRating";

function MovieDetails({
  selectedMovie,
  isLoadingDetails,
  errorDetails,
  userRating,
  setUserRating,
  onCloseMovie,
  onAddWatched,
  watched,
  onDeleteWatched,
}) {
  const maxRating = 10;

  return (
    <div className="details">
      {isLoadingDetails ? (
        <div>Loading details...</div>
      ) : errorDetails ? (
        <div>{errorDetails}</div>
      ) : (
        <>
          <header>
            <img src={selectedMovie.Poster} alt={selectedMovie.Title} />
            <section>
              <h2>{selectedMovie.Title}</h2>
              <p>
                Year: {selectedMovie.Released} - {selectedMovie.Runtime}
              </p>
              <p>Genre: {selectedMovie.Genre}</p>
              <p>⭐ {selectedMovie.imdbRating}</p>
            </section>
          </header>
          <div className="rating">
            <StarsRating
              maxRating={maxRating}
              size={24}
              rating={userRating}
              setRating={setUserRating}
            />
            {userRating > 0 && (
              <button
                className="btn-add"
                onClick={() => {
                  onAddWatched({
                    ...selectedMovie,
                    userRating,
                  });
                  setUserRating(0);
                  onCloseMovie();
                }}
              >
                Add to watched
              </button>
            )}
          </div>
        </>
      )}
    </div>
  );
}

export default MovieDetails;
